   111	            if (alreadyEmitted != null && alreadyEmitted) {
   112	                return;
   113	            }
   114	
   115	            Long term = terminalTs.value();
   116	            if (term != null && term >= 0 && value.timestamp > term) {
   117	                return;
   118	            }
