   129	            Long last = lastSubmitTs.value();
   130	            if (last == null) {
   131	                cur = 1;
   132	            } else {
   133	                long gap = value.timestamp - last;
   134	                if (gap >= sessionGapMicros) {
   135	                    max = Math.max(max, cur);
   136	                    cur = 1;
   137	                } else {
   138	                    cur = cur + 1;
   139	                }
   140	            }
   141	
   142	            lastSubmitTs.update(value.timestamp);
   143	            currentStageCount.update(cur);
   144	            maxStageCount.update(max);
   145	        }
