   151	                return;
   152	            }
   153	            if (!value.isTerminal()) {
   154	                return;
   155	            }
   156	
   157	            Long oldTerm = terminalTs.value();
   158	            long newTerm = value.timestamp;
   159	
   160	            if (oldTerm == null || newTerm > oldTerm) {
   161	                if (oldTerm != null) {
   162	                    ctx.timerService().deleteEventTimeTimer(oldTerm + 1);
   163	                }
   164	                terminalTs.update(newTerm);
   165	                ctx.timerService().registerEventTimeTimer(newTerm + 1);
   166	            }
   167	        }
